const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../lib/first-signal.cjs');
const { EventEmitter } = require('node:events');
test('one invocation, receiver, arguments, and existing listeners', () => {
  const emitter = new EventEmitter(); const seen=[]; let persistent=0;
  emitter.on('ready',()=>persistent++);
  const returned=app.firstSignal(emitter,'ready',function(...args) {
    assert.equal(this,emitter); seen.push(args);
  });
  assert.equal(returned,emitter);
  emitter.emit('ready',7,'north'); emitter.emit('ready',8,'south');
  assert.deepEqual(seen,[[7,'north']]); assert.equal(persistent,2);
  assert.equal(emitter.listenerCount('ready'),1);
});
test('remove before invocation so synchronous re-emission is safe', () => {
  const emitter=new EventEmitter(); const event=Symbol('ready'); let calls=0;
  app.firstSignal(emitter,event,()=>{ calls++; if(calls===1) emitter.emit(event); });
  emitter.emit(event); assert.equal(calls,1); assert.equal(emitter.listenerCount(event),0);
});
test('registration is lazy and appends after existing listeners', () => {
  const emitter = new EventEmitter(); const seen = [];
  emitter.on('ready', () => seen.push('existing'));
  app.firstSignal(emitter, 'ready', () => seen.push('first'));
  assert.deepEqual(seen, []);
  assert.equal(emitter.listenerCount('ready'), 2);
  emitter.emit('unrelated');
  assert.deepEqual(seen, []);
  emitter.emit('ready'); emitter.emit('ready');
  assert.deepEqual(seen, ['existing', 'first', 'existing']);
});
